={
  "model": "claude-3-5-sonnet-20241022",
  "max_tokens": 1024,
  "temperature": 0,
  "system": "You are a strict data extraction assistant for " + $node['Config & Environment Loader'].json.BUSINESS_NAME + ". Return ONLY a valid JSON object matching: { name, phone, location, job_type, urgency, description, photo_links, preferred_slot, needs_human, reason_if_needs_human }.",
  "messages": [
    { "role": "user", "content": "Extract lead details: " + ($json.body.transcript || $json.body.message || JSON.stringify($json.body)) }
  ]
}

={
  "fields": {
    "LeadID": "LD-" + $now.format('X'),
    "Name": JSON.parse($node['Claude Structured Extraction'].json.content[0].text).name || 'Unknown',
    "Phone": JSON.parse($node['Claude Structured Extraction'].json.content[0].text).phone || '',
    "Location": JSON.parse($node['Claude Structured Extraction'].json.content[0].text).location || '',
    "JobType": JSON.parse($node['Claude Structured Extraction'].json.content[0].text).job_type || 'General',
    "Urgency": JSON.parse($node['Claude Structured Extraction'].json.content[0].text).urgency || 'High',
    "Description": JSON.parse($node['Claude Structured Extraction'].json.content[0].text).description || '',
    "Status": "Escalated to Human",
    "NextAction": "Urgent contractor callback: " + (JSON.parse($node['Claude Structured Extraction'].json.content[0].text).reason_if_needs_human || 'Explicit ask')
  }
}

={
  "fields": {
    "LeadID": "LD-" + $now.format('X'),
    "Name": JSON.parse($node['Claude Structured Extraction'].json.content[0].text).name,
    "Phone": JSON.parse($node['Claude Structured Extraction'].json.content[0].text).phone,
    "Location": JSON.parse($node['Claude Structured Extraction'].json.content[0].text).location,
    "JobType": JSON.parse($node['Claude Structured Extraction'].json.content[0].text).job_type,
    "Urgency": JSON.parse($node['Claude Structured Extraction'].json.content[0].text).urgency,
    "Description": JSON.parse($node['Claude Structured Extraction'].json.content[0].text).description,
    "Status": "Qualified",
    "NextAction": "Proceed to Calendar Scheduling"
  }
}
